<?php
require_once '../config/database.php';require_once '../includes/auth.php';require_once '../includes/ui.php';requireAdmin();if(empty($_SESSION['csrf_support']))$_SESSION['csrf_support']=bin2hex(random_bytes(32));$csrf=$_SESSION['csrf_support'];$id=(int)($_GET['id']??0);
$list=$conn->query("SELECT c.id,c.status,c.created_at,c.updated_at,u.name,u.email,(SELECT message FROM support_messages WHERE conversation_id=c.id ORDER BY id DESC LIMIT 1) last_message FROM support_conversations c JOIN users u ON u.id=c.user_id ORDER BY CASE WHEN c.status='OPEN' THEN 0 ELSE 1 END,c.updated_at DESC");
$selected=null;if($id){$s=$conn->prepare('SELECT c.id,c.status,u.name,u.email FROM support_conversations c JOIN users u ON u.id=c.user_id WHERE c.id=?');$s->bind_param('i',$id);$s->execute();$selected=$s->get_result()->fetch_assoc();$s->close();}
$titleForTop='Support Chat';renderHead('Support Chat Admin');renderAdminNav('support'); ?>
<div class="content animate-in"><div class="section-head"><div><h1 class="hero-title">Support Chat</h1><p class="muted">Inbox pesan pengguna.</p></div></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:18px"><section class="card"><h2>Percakapan</h2><?php if($list&&$list->num_rows):while($c=$list->fetch_assoc()):?><a class="card" style="display:block;margin:8px 0;text-decoration:none;padding:12px" href="/admin/support.php?id=<?= (int)$c['id'] ?>"><b><?= e($c['name']) ?></b> <span class="pill <?= $c['status']==='OPEN'?'pill-green':'pill-yellow' ?>"><?= e($c['status']) ?></span><div class="muted"><?= e($c['email']) ?></div><div><?= e($c['last_message']?:'Belum ada pesan') ?></div></a><?php endwhile;else:?><p class="muted">Belum ada percakapan.</p><?php endif;?></section><section class="card"><?php if($selected):?><h2><?= e($selected['name']) ?></h2><p class="muted"><?= e($selected['email']) ?> · <?= e($selected['status']) ?></p><div id="msgs" style="height:52vh;min-height:280px;overflow:auto;border:1px solid #ddd;border-radius:14px;padding:14px;display:flex;flex-direction:column;gap:12px"></div><form id="form" style="display:flex;gap:8px;margin-top:12px"><input id="csrf" type="hidden" value="<?= e($csrf) ?>"><textarea id="msg" class="form-control" rows="2" maxlength="4000" required style="flex:1" placeholder="Balas pengguna..." <?= $selected['status']==='CLOSED'?'disabled':'' ?>></textarea><button id="send" class="btn btn-blue" type="submit" <?= $selected['status']==='CLOSED'?'disabled':'' ?>>Balas</button></form><form id="statusform" style="margin-top:10px"><button id="statusbtn" class="btn btn-light" type="submit" data-status="<?= e($selected['status']) ?>"><?= $selected['status']==='OPEN'?'Tandai Selesai':'Buka Kembali' ?></button><span id="fb" class="muted"></span></form><?php else:?><p class="muted">Pilih percakapan di sebelah kiri.</p><?php endif;?></section></div></div>
<?php if($selected):?><script>(()=>{const id=<?= $id ?>,csrf=document.getElementById('csrf').value,list=document.getElementById('msgs'),form=document.getElementById('form'),input=document.getElementById('msg'),send=document.getElementById('send'),sf=document.getElementById('statusform'),sb=document.getElementById('statusbtn'),fb=document.getElementById('fb');let sig='';function bubble(m){let w=document.createElement('div');w.style.alignSelf=m.sender_role==='ADMIN'?'flex-end':'flex-start';let l=document.createElement('small');l.className='muted';l.textContent=(m.sender_role==='ADMIN'?'Admin':'Pengguna')+' · '+m.created_at;let b=document.createElement('div');b.style.cssText='padding:10px;border-radius:12px;white-space:pre-wrap;overflow-wrap:anywhere;background:'+(m.sender_role==='ADMIN'?'#2563eb':'#eee')+';color:'+(m.sender_role==='ADMIN'?'white':'#222');b.textContent=m.message;w.append(l,b);return w}async function load(){try{let r=await fetch('/support-chat.php?action=fetch&conversation_id='+id,{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Gagal memuat');let n=d.messages.map(m=>m.id).join(',');if(n!==sig){list.replaceChildren();if(!d.messages.length){let p=document.createElement('p');p.textContent='Belum ada pesan.';list.append(p)}else d.messages.forEach(m=>list.append(bubble(m)));list.scrollTop=list.scrollHeight;sig=n}input.disabled=d.status==='CLOSED';send.disabled=input.disabled}catch(e){fb.textContent=e.message}}form.onsubmit=async e=>{e.preventDefault();let message=input.value.trim();if(!message)return;send.disabled=true;try{let r=await fetch('/support-chat.php?action=send',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({conversation_id:id,message,csrf})}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Gagal kirim');input.value='';fb.textContent='Terkirim';await load()}catch(e){fb.textContent=e.message}finally{send.disabled=input.disabled}};sf.onsubmit=async e=>{e.preventDefault();let status=sb.dataset.status==='OPEN'?'CLOSED':'OPEN';sb.disabled=true;try{let r=await fetch('/support-chat.php?action=status',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({conversation_id:id,status,csrf})}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Gagal ubah status');location.reload()}catch(e){fb.textContent=e.message;sb.disabled=false}};load();setInterval(load,4000)})();</script><?php endif;?><?php renderFooter(); ?>